import math
from statistics import NormalDist


def phi(z):
    return math.exp(-z * z / 2) / math.sqrt(2 * math.pi)


def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 1:
            total = total + 4 * f(a + i * h)
        else:
            total = total + 2 * f(a + i * h)
    return total * h / 3


def Phi(z):
    return 0.5 + simpson(phi, 0, z, 100)


def between(label, mu, sigma, a, b):
    za = (a - mu) / sigma
    zb = (b - mu) / sigma
    p = Phi(zb) - Phi(za)
    check = NormalDist(mu, sigma).cdf(b) - NormalDist(mu, sigma).cdf(a)
    print(label)
    print(f"  z from {za:.4f} to {zb:.4f}, P = Phi(zb) - Phi(za) = {p:.4f}, NormalDist: {check:.4f}")


def above(label, mu, sigma, a):
    z = (a - mu) / sigma
    p = 1 - Phi(z)
    print(label)
    print(f"  z = {z:.4f}, P = 1 - Phi(z) = {p:.4f}, NormalDist: {1 - NormalDist(mu, sigma).cdf(a):.4f}")


def below(label, mu, sigma, a):
    z = (a - mu) / sigma
    print(label)
    print(f"  z = {z:.4f}, P = Phi(z) = {Phi(z):.4f}, NormalDist: {NormalDist(mu, sigma).cdf(a):.4f}")


