import math


def phi(z):
    return math.exp(-z * z / 2) / math.sqrt(2 * math.pi)


def simpson(f, a, b, n):
    h = (b - a) / n
    total = f(a) + f(b)
    for i in range(1, n):
        if i % 2 == 1:
            total = total + 4 * f(a + i * h)
        else:
            total = total + 2 * f(a + i * h)
    return total * h / 3


def Phi(z):
    return 0.5 + simpson(phi, 0, z, 100)


count = int(input())
for i in range(count):
    parts = input().split()
    kind = parts[0]
    nums = [float(v) for v in parts[1:]]
    mu, sigma = nums[0], nums[1]
    za = (nums[2] - mu) / sigma
    if kind == "between":
        zb = (nums[3] - mu) / sigma
        p = Phi(zb) - Phi(za)
    elif kind == "above":
        p = 1 - Phi(za)
    else:
        p = Phi(za)
    print(f"Problem {i + 1}: {kind} {p:.4f}")
